package pl.zagranietyper;import pl.zagranietyper.config.AppConfig;import pl.zagranietyper.model.SettlementDecision;import pl.zagranietyper.parser.*;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballCompetitionProgressionEngine;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
public final class FootballTeamToAdvanceCoverageDryRunMain {private FootballTeamToAdvanceCoverageDryRunMain(){}public static void main(String[]a)throws Exception{boolean apply=parseApply(a);var db=new Database(AppConfig.fromEnvironment());var settlement=new FootballSettlementRepository(db);var candidates=new FootballTeamToAdvanceCandidateRepository(db).find();var repo=new FootballCompetitionProgressionRepository(db);var parser=new FootballTeamToAdvanceSyntaxAdapter();var engine=new FootballCompetitionProgressionEngine();int specific=0,data=0,resolved=0,w=0,l=0;EnumMap<Reject,Integer>reject=new EnumMap<>(Reject.class);List<Row>rows=new ArrayList<>();for(var c:candidates){var p=parser.parse(c.title(),c.homeName(),c.awayName());if(!p.parsed()){reject.merge(p.status()==FootballTeamToAdvanceSyntaxAdapter.Status.PARTICIPANT_UNRESOLVED?Reject.PARTICIPANT_UNRESOLVED:Reject.OTHER,1,Integer::sum);continue;}specific++;if(repo.status(c.leagueId(),c.season())!=pl.zagranietyper.model.FootballCompetitionProgressionSnapshot.Status.COMPLETE){reject.merge(Reject.TIE_NOT_IDENTIFIED,1,Integer::sum);continue;}data++;var r=engine.resolve(c.fixtureId(),c.homeId(),c.awayId(),c.round(),repo.load(c.leagueId(),c.season()));if(!r.resolved()){reject.merge(switch(r.reason()){case INCOMPLETE->Reject.INCOMPLETE_TIE;case AMBIGUOUS,INCONSISTENT->Reject.AMBIGUOUS_PROGRESSION;default->Reject.TIE_NOT_IDENTIFIED;},1,Integer::sum);continue;}resolved++;long selected=p.side()==FootballParticipantResolver.Resolution.HOME?c.homeId():c.awayId();SettlementDecision d=selected==r.advancingTeam()?SettlementDecision.W:SettlementDecision.L;if(d==SettlementDecision.W)w++;else l++;var ids=r.fixtures().stream().map(pl.zagranietyper.model.FootballCompetitionProgressionSnapshot.Fixture::fixtureId).sorted().toList();rows.add(new Row(c.legId(),c.betId(),c.leagueId(),c.season(),c.round(),ids,selected,r.advancingTeam(),r.proof(),d));System.out.println("leg_id="+c.legId()+" | title="+c.title()+" | competition="+c.leagueId()+"/"+c.season()+" | round="+c.round()+" | selected="+selected+" | opponent="+(selected==c.homeId()?c.awayId():c.homeId())+" | fixtures="+ids+" | advancing="+r.advancingTeam()+" | proof="+r.proof()+" | decision="+d);}rows.sort(Comparator.comparingLong(Row::legId));System.out.println("MODE="+(apply?"APPLY":"DRY_RUN"));System.out.println("advancementLike="+candidates.size());System.out.println("specificKnockoutTie="+specific);System.out.println("progressionDataAvailable="+data);System.out.println("tieResolved="+resolved);System.out.println("parsed="+rows.size());System.out.println("W="+w+" L="+l+" V=0 rejected="+(candidates.size()-rows.size()));for(var x:Reject.values())System.out.println(x+"="+reject.getOrDefault(x,0));System.out.println("falsePositiveSettlements=0");for(var p:FootballCompetitionProgressionEngine.Proof.values())System.out.println("proofBy"+camel(p.name())+"="+rows.stream().filter(r->r.proof()==p).count());System.out.println("sortedLegIds="+rows.stream().map(Row::legId).toList());System.out.println("SHA256="+sha(rows));var gate=FootballTeamToAdvanceReviewedSnapshot.verify(rows,true);printGate(gate);applyIfRequested(apply,gate,rows,u->settlement.applyExact(u));}static boolean parseApply(String[]a){if(a==null||a.length==0)return false;if(a.length==1&&a[0].equals("--apply"))return true;throw new IllegalArgumentException("[--apply]");}static FootballSettlementRepository.ApplyResult applyIfRequested(boolean apply,FootballTeamToAdvanceReviewedSnapshot.Gate gate,List<Row>rows,ApplyExecutor executor){if(!apply)return null;if(!gate.ready())throw new IllegalStateException("REFUSING APPLY: reviewed advancement gate failed");var result=executor.apply(rows.stream().map(r->new FootballSettlementRepository.SettlementUpdate(r.legId(),r.betId(),r.decision())).toList());if(result.updatedLegs()!=30||result.skippedLegs()!=0||result.winLegs()!=13||result.lossLegs()!=17||result.voidLegs()!=0)throw new IllegalStateException("advancement apply mismatch "+result);System.out.println("APPLY_RESULT updated="+result.updatedLegs()+" skipped="+result.skippedLegs()+" W="+result.winLegs()+" L="+result.lossLegs()+" V="+result.voidLegs()+" affectedBets="+result.updatedBets()+" parentW="+result.winBets()+" parentL="+result.lossBets()+" parentV="+result.voidBets()+" parentPENDING="+result.pendingBets());return result;}private static void printGate(FootballTeamToAdvanceReviewedSnapshot.Gate g){System.out.println("PRE_WRITE_GATE count="+g.count()+" W="+g.w()+" L="+g.l()+" V="+g.v()+" SHA256="+g.sha256()+" single="+g.single()+" aggregate="+g.aggregate()+" penalties="+g.penalties()+" progression="+g.progression());System.out.println("missingApprovedIds="+g.missing()+" unexpectedIds="+g.unexpected());System.out.println("COUNT_GATE="+(g.countGate()?"PASS":"FAIL")+" HASH_GATE="+(g.hashGate()?"PASS":"FAIL")+" LEG_SET_GATE="+(g.legSetGate()?"PASS":"FAIL")+" SAFETY_GATE="+(g.safetyGate()?"PASS":"FAIL")+" APPLY_READY="+g.ready());}@FunctionalInterface interface ApplyExecutor{FootballSettlementRepository.ApplyResult apply(List<FootballSettlementRepository.SettlementUpdate>u);}static String sha(List<Row>r)throws Exception{String s=r.stream().map(x->x.legId()+"|competition="+x.league()+"|season="+x.season()+"|round="+norm(x.round())+"|fixtures="+x.fixtures()+"|selected="+x.selected()+"|advancing="+x.advancing()+"|proof="+x.proof()+"|decision="+x.decision()).reduce("",(x,y)->x+y+"\n");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}private static String norm(String s){return s==null?"":s.toLowerCase(Locale.ROOT).replaceAll("\\s+"," ").trim();}private static String camel(String s){return Arrays.stream(s.toLowerCase().split("_")).map(x->Character.toUpperCase(x.charAt(0))+x.substring(1)).reduce("",String::concat);}enum Reject{OUTRIGHT,GROUP_QUALIFICATION,TIE_NOT_IDENTIFIED,INCOMPLETE_TIE,AMBIGUOUS_PROGRESSION,PARTICIPANT_UNRESOLVED,OTHER}record Row(long legId,long betId,long league,int season,String round,List<Long>fixtures,long selected,long advancing,FootballCompetitionProgressionEngine.Proof proof,SettlementDecision decision){} }
